TLM.f("Tempora/Pent02-5",{"officium":"Sacratissimi Cordis Domini Nostri Jesu Christi","rule":["Gloria","Credo","Prefatio=Cord","No Commemoratio"],"ruleInherited":["ex Tempora/Pent01-4","Gloria","Credo","Prefatio=Nat","Prefatio1960=Trinitate","Gloria","Credo","Prefatio=Communis","Sequentia","Gloria","Credo","Prefatio=Trinitate"],"fallback":"Tempora/Pent02-0r","from":{"Commemoratio Oratio":"Tempora/Pent02-0r","Commemoratio Secreta":"Tempora/Pent02-0r","Commemoratio Postcommunio":"Tempora/Pent02-0r"},"sections":{"Introitus":[{"k":"ref","la":"Ps 32:11; 32:19"},{"k":"text","la":"Cogitatiónes Cordis ejus in generatióne et generatiónem: ut éruat a morte ánimas eórum et alat eos in fame. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 32:1"},{"k":"text","la":"Exsultáte, justi, in Dómino: rectos decet collaudátio."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Cogitatiónes Cordis ejus in generatióne et generatiónem: ut éruat a morte ánimas eórum et alat eos in fame. (Alleluia, alleluia.)"}],"Oratio":[{"k":"text","la":"Deus, qui nobis in Corde Fílii tui, nostris vulneráto peccátis, infinítos dilectiónis thesáuros misericórditer largíri dignáris: concéde, quǽsumus; ut, illi devótum pietátis nostræ præstántes obséquium, dignæ quoque satisfactiónis exhibeámus offícium."},{"k":"macro","name":"Per eumdem"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Ephésios"},{"k":"ref","la":"Eph 3:8-12, 14-19"},{"k":"text","la":"Fratres: Mihi, ómnium sanctórum mínimo, data est grátia hæc, in géntibus evangelizáre investigábiles divítias Christi, et illumináre omnes, quæ sit dispensátio sacraménti abscónditi a sǽculis in Deo, qui ómnia creávit: ut innotéscat principátibus et potestátibus in cœléstibus per Ecclésiam multifórmis sapiéntia Dei, secúndum præfinitiónem sæculórum, quam fecit in Christo Jesu, Dómino nostro, in quo habémus fidúciam et accéssum in confidéntia per fidem ejus. Hujus rei grátia flecto génua mea ad Patrem Dómini nostri Jesu Christi, ex quo omnis patérnitas in cœlis ei in terra nominátur, ut det vobis, secúndum divítias glóriæ suæ, virtúte corroborári per Spíritum ejus in interiórem hóminem, Christum habitáre per fidem in córdibus vestris: in caritáte radicáti et fundáti, ut póssitis comprehéndere cum ómnibus sanctis, quæ sit latitúdo, et longitúdo, et sublímitas, et profúndum: scire étiam supereminéntem sciéntiæ caritátem Christi, ut impleámini in omnem plenitúdinem Dei."}],"Graduale":[{"k":"ref","la":"Ps 24:8-9"},{"k":"text","la":"Dulcis et rectus Dóminus: propter hoc legem dabit delinquéntibus in via."},{"k":"text","la":"Díriget mansúetos in judício, docébit mites vias suas.","mark":"V"},{"k":"ref","la":"Mt 11:29"},{"k":"text","la":"Allelúja, allelúja. Tóllite jugum meum super vos, et díscite a me, quia mitis sum et húmilis Corde, et inveniétis réquiem animábus vestris. Allelúja."}],"GradualeP":[{"k":"ref","la":"Matt 11:29; 11:28"},{"k":"text","la":"Allelúja, allelúja. Tóllite jugum meum super vos, et díscite a me, quia mitis sum et húmilis Corde: et inveniétis réquiem animábus vestris. Allelúja."},{"k":"text","la":"Veníte ad me, omnes qui laborátis, et oneráti estis, et ego refíciam vos. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 102:8-10"},{"k":"text","la":"Miséricors et miserátor Dóminus, longánimis, et multum miséricors,"},{"k":"text","la":"Non in perpétuum irascétur, neque in ætérnum comminábitur.","mark":"V"},{"k":"text","la":"Non secúndum peccáta nostra fecit nobis, neque secúndum iniquitátes nostras retríbuit nobis.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 19:31-37"},{"k":"text","la":"In illo témpore: Judǽi - quóniam Parascéve erat, - ut non remanérent in cruce córpora sábbato - erat enim magnus dies ille sábbati, - rogavérunt Pilátum, ut frangeréntur eórum crura, et tolleréntur. Venérunt ergo mílites: et primi quidem fregérunt crura et alteríus, qui crucifíxus est cum eo. Ad Jesum autem cum veníssent, ut vidérunt eum jam mórtuum, non fregérunt ejus crura, sed unus mílitum láncea latus ejus apéruit, et contínuo exívit sanguis et aqua. Et qui vidit, testimónium perhíbuit: et verum est testimónium ejus. Et ille scit quia vera dicit, ut et vos credátis. Facta sunt enim hæc ut Scriptúra implerétur: Os non comminuétis ex eo. Et íterum alia Scriptúra dicit: Vidébunt in quem transfixérunt."}],"Offertorium":[{"k":"ref","la":"Ps 68:21"},{"k":"text","la":"Impropérium exspectávi Cor meum et misériam: et sustínui, qui simul mecum contristarétur, et non fuit: consolántem me quæsívi, et non invéni."}],"Secreta":[{"k":"text","la":"Réspice, quǽsumus, Dómine, ad ineffábilem Cordis dilécti Fílii tui caritátem: ut quod offérimus sit tibi munus accéptum et nostrórum expiátio delictórum."},{"k":"macro","name":"Per eumdem"}],"Communio":[{"k":"ref","la":"Joannes 19:34"},{"k":"text","la":"Unus mílitum láncea latus ejus apéruit, et contínuo exívit sanguis et aqua."}],"Postcommunio":[{"k":"text","la":"Prǽbeant nobis, Dómine Jesu, divínum tua sancta fervórem: quo dulcíssimi Cordis tui suavitáte percépta; discámus terréna despícere, et amáre cœléstia:"},{"k":"macro","name":"Qui vivis"}],"Commemoratio Oratio":[{"k":"rubric","la":"Pro Octava SSmi. Corporis Christi"},{"k":"text","la":"Deus, qui nobis sub Sacraménto mirábili passiónis tuæ memóriam reliquísti: tríbue, quǽsumus, ita nos Córporis et Sánguinis tui sacra mystéria venerári; ut redemptiónis tuæ fructum in nobis júgiter sentiámus:"},{"k":"macro","name":"Qui vivis"}],"Commemoratio Secreta":[{"k":"rubric","la":"Pro Octava Ssmi Corporis Christi"},{"k":"text","la":"Ecclésiæ tuæ, quǽsumus, Dómine, unitátis et pacis propítius dona concéde: quæ sub oblátis munéribus mýstice designántur."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Postcommunio":[{"k":"rubric","la":"Pro Octava Ssmi Corporis Christi"},{"k":"text","la":"Fac nos, quǽsumus, Dómine, divinitátis tuæ sempitérna fruitióne repléri: quam pretiósi Córporis et Sánguinis tui temporális percéptio præfigúrat:"},{"k":"macro","name":"Qui vivis"}],"OffertoriumP":[{"k":"ref","la":"Ps 39:7-9"},{"k":"text","la":"Holocáustum et pro peccáto non postulásti; tunc dixi: Ecce, vénio. In cápite libri scriptum est de me ut fácerem voluntátem tuam: Deus meus, volui, et legem tuam in médio Cordis mei, allelúja."}],"CommunioP":[{"k":"ref","la":"Joannes 7:37"},{"k":"text","la":"Si quis sitit, véniat ad me et bibat, allelúja, allelúja."}]},"hr":{"845aac0f31343c1b":{"t":"Ps 32, 11 i 19, Ps 32, 1\n(Ps 32, 11 i 19) Misli su Srca njegova usmjerene od pokoljenja na pokoljenje, da im izbavi duše od smrti i da ih gladne nahrani. (Ps 32, 1) Radujte se, pravednici, u Gospodinu, pravednima dolikuje da ga hvale.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 32, 11 i 19) Misli su Srca njegova usmjerene od pokoljenja na pokoljenje, da im izbavi duše od smrti i da ih gladne nahrani.","kn":"(Ps. 32, 11, 19). Misli srca njegova od koljena do koljena, da kbavi duše njihove od smrti i da ih Blagdan presv. Srca Isusova nahrani ti doba gladi. (Ps. 32, 1). Kličite pravedni, Gospodinu, pravednici treba da hvale Gospodina.’ Slava Ocu . . . Misli srca njegova . . .","knRef":"Kniewald 1942, str. 370–371 (snimka 186) (OCR)"},"442c58cf4cc1dc3b":{"t":"<i>Pomolimo se</i>.\nBože, koji se dostojiš milosrdno nam darivati beskrajno blago ljubavi u Srcu svoga Sina ranjenom našim grijesima, podaj, molimo, da mu mi, koji ga častimo svojom odanom pobožnošću, dademo i doličnu zadovoljštinu.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji se dostojiš milostivo nam darivati neizmjerno blago ljubavi svoje u Srcu Sina svoga, ranjenoga našim grijesima, dopusti, molimo, da mu prinosimo čast naše odane pobožnosti i ujedno izvršimo dužnost dostojne zadovoljštine, po istom G. n.","knRef":"Kniewald 1942, str. 372–373 (snimka 187) (OCR)"},"81ba08e8396bc8fe":{"t":"Ef 3, 8-12 i 14-19\nČitanje Poslanice bl. Pavla apostola Efežanima. Braćo, meni, najmanjemu od svih svetih, dana je milost da poganima navijestim nedokučivo bogatstvo Kristovo i da svima protumačim, kako se ostvarilo otajstvo oduvijek skriveno u Bogu koji je sve stvorio, da nebeska poglavarstva i vlasti doznaju po Crkvi za mnogovrsnu mudrost Božju, koju je po vječnoj odluci izveo u Kristu Isusu, našem Gospodinu. U njemu imamo pouzdanje i slobodan pristup Bogu po vjeri u njega. Zato prigibam svoja koljena pred Ocem Gospodina našega Isusa Krista, od koga potječe svako očinstvo na nebu i na zemlji, da vam po svojoj obilnoj slavi dade, te njegovim Duhom ojačate za unutrašnjeg čovjeka, da po vjeri Krist stanuje u vašim srcima i da u ljubavi ukorijenjeni i utvrđeni možete sa svim svetima razumjeti širinu i dužinu i visinu i dubinu i spoznati Kristovu ljubav, koja nadilazi svaku spoznaju, da se napunite svakom puninom Božjom.","kn":"Čitanje poslanice bi. Pavla apostola Efežanima (3, 8-19). Braćo! Meni, najmanjemu od svih svetih, dana je ova milost, da navješćujem neznabošcima nedokučivo Kristovo bogatstvo, i da svima javim, kakva je uredba tajne, koja je od vijeka sakrivena u Bogu, koji je sve stvorio. Da po Crkvi doznaju za nebeska poglavarstva i vlasti, mnogovrsnu mudrost Božju, po vječnoj odredbi, koju je izvršio u Isusu, Gospodinu našemu. U njemu imamo pouzdanje i slobodu po njegovoj vjeri. Zatoi vas molim, da ne klonete radi mojih nevolja, koje trpim za vas, što je vaša slava. Zato prlgibam svoja koljena pred Ocem Gospodina našega Isusa Krista, po kojemu postaje svaka obitelj na nebu i na zemlji, da vam po svojoj obilnoj slavi i dobroti dadne, da se po njegovu duhu pojačate za unutrašnjega Čovjeka, da po vjeri Krist stanuje u vašim srcima. Da ukorijenjeni i utvrđeni u ljubavi sa svima svetima možete dokučiti, koja je širina i dužma i visina i dubina i da možete poznati Kristovu ljubav, koja prelazi svako znanje, da se napunite svakim Božjim obiljem.","knRef":"Kniewald 1942, str. 372–373 (snimka 187) (OCR)"},"2a0a16380afcbf8e":{"t":"Ps 24, 8-9\nDobar je i pravedan Gospodin. Stoga će dati zakon onima koji su zalutali na putu. On vodi krotke u pravdi, blage uči svojim putovima.\n\nMt 11, 29\n<i>Aleluja</i>, <i>aleluja</i>.\nUzmite jaram moj na sebe i učite se od mene, jer sam blaga i ponizna Srca, i naći ćete mir svojim dušama. <i>Aleluja</i>.","kn":"(Ps. 24, 8, 9). Dobar je i pravedan Gospodin, stoga daje zakon onima, koji zalaze s puta. On vodi smjerne pravo i uči blage putovima svojim.\n\nAleluja, aleluja. (Mt. 11, 29). Uzmite na sebe jaram .moj i učite se od mene, jer sam blaga i ponizna srca i naći čete mir dušama svojim, aleluja.","knRef":"Kniewald 1942, str. 372–373 (snimka 187) (OCR)"},"a6d56eab9a6d7bca":{"t":"Iv 19, 31-37\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme, jer je bio dan priprave i da tjelesa ne bi ostala na križu u subotu (a one je subote bio velik blagdan) Židovi zamole Pilata da im se prebiju noge pa da se skinu. Vojnici dođu i prebiju noge obojici raspetih s Isusom. Ali, kad su došli do Isusa i vidjeli da je već umro, ne prebiju mu noge, nego jedan vojnik kopljem otvori njegova rebra, i odmah poteče krv i voda. Onaj koji je to vidio svjedoči i njegovo je svjedočanstvo istinito. On zna da govori istinu, da i vi vjerujete. Ovo se dogodilo, da se ispuni Pismo: Neće prebiti ni jednu njegovu kost. I drugo Pismo koje kaže: Vidjet će koga su proboli.","kn":"t Slijedi sveto evanđelje po Ivanu (19, 31-37). U ono vrijeme, jer je bio dan Priprave, da ne bi tjelesa ostala na križu u subotu (a bio je veliki dan ona subota), Židovi zamoliše Pilata, da im se prebiju noge i da se skinu. Vojnici dođu i prebiju noge jednomu i drugomu, koji j j bio s njim raspet. Ali kad su došli do Isusa i vidjeli, da je već umro, nijesu mu prebijali kostiju, nego mu jedan od vojnika kopljem otvori bok i odmah poteče krv i voda. I posvjedočio je onaj, koji je vidio, a njegovo je svjedočanstvo istinito. On zna, da govori istinu, da i yi vjerujete. Jer se to dogodilo, da se ispuni Pismo: Ne ćete prebiti nijedne od njegovih kostiju* I opet kaže drugo Pismo: Vidjet će, koga su proboli.”","knRef":"Kniewald 1942, str. 372–373 (snimka 187) (OCR)"},"a02705046a3fccb4":{"t":"Ps 68, 21\nMoje je Srce očekivalo porugu i nevolju. Čekao sam hoće li se tko sažaliti nada mnom, a nije ga bilo. Tražio sam hoće li me tko utješiti, a nisam ga našao.","kn":"(Ps. 68, 21, 22). Prepuno je srce moje poruge i nevolje. Čekao sam, tko bi sa mnom tugovao i nije ga bUo, tražio sam, tko bi me utješio, i . nikoga ne nađoh; za jelo mi dadoše žuč i u žeđi me mojoj napojiše octom.","knRef":"Kniewald 1942, str. 226–227 (snimka 114) (OCR)"},"ff4cace967db4b4e":{"t":"Pogledaj, molimo, Gospodine, na neizrecivu ljubav Srca svoga ljubljenog Sina, da ono što prinosimo bude tebi mio dar, a za naše grijehe pomirba.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, pogledaj na neizrecivu ljubav Srca svoga ljubljenoga Sina i podaj, da naša žrtva bude Tebi prijatni dar i okajanje naših grijeha, po istom G. n.","knRef":"Kniewald 1942, str. 372–373 (snimka 187) (OCR)"},"8813fe48bbec8a80":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože: – ti si htio da tvoj Jedinorođenac viseći na križu bude proboden vojnikovim kopljem, da otvoreno Srce, svetište darežljivosti božanske, izlijeva na nas bujice milosrđa i milosti; te da Srce koje nikad ne prestaje plamtjeti ljubavlju prema nama, mir bude pobožnim, a raskajanima otvoreno utočište spasenja. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Gospodine sveti, Oče svemo'gući, vječni Bože, koji S'i htio da vojničko koplje probo-de Jedinorođenoga Tvoga, kad je visio na križu, te njegovo otvoreno srce, ovo svetište božanske darežljivosti, izlije na nas struje milosrđa i dobrote, i postane mirom pobožnih i uvijek otvoreno utočište pokajnicima, jer nikad ne prestaje goriti od ljubavi prama nama. I zato pjevamo pjesmu slave Tvoje s anđelima i s arkanđelima, s prijestolima i s gospodstvima, sa svom silom nebeske vojske bez prestanka govoreći:","knRef":"Kniewald 1942, str. 374–375 (snimka 188) (OCR)"},"ffe1b36af37945d2":{"t":"Iv 19, 34\nJedan vojnik kopljem otvori njegova rebra i odmah poteče krv i voda.","kn":"(Iv. 19, 34). Jedan je vojnik kopljem otvorio njegova rebra i odmah poteče krv i voda.","knRef":"Kniewald 1942, str. 374–375 (snimka 188) (OCR)"},"2897c512bd25cbf7":{"t":"<i>Pomolimo se</i>.\nNapunila nas, Gospodine Isuse, tvoja sveta otajstva božanskim žarom, da po njima, okusivši milinu tvoga slatkog Srca, naučimo prezirati zemaljsko a ljubiti nebesko:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Raspalile, Gospodine Isuse, Tvoje svetinje u nama božansku revnost, te primivši slatkoću slatkoga srca Tvoga uzmognemo prezreti zemaljsko 1 ljubiti ono, što je nebesko, koji živiš i kraljuješ . . .","knRef":"Kniewald 1942, str. 374–375 (snimka 188) (OCR)"}}});
